for f in /opt/miniconda3/envs/testbed/lib/python3.10/encodings/*.py; do
    python -c "
import encodings
import sys
try:
    encoding_name = f.replace('/opt/miniconda3/envs/testbed/lib/python3.10/encodings/', '').replace('.py', '')
    encoding = encodings.lookup(encoding_name)
    # Check if decoding_table exists and has any \ufffe entries
    if hasattr(encoding, 'decoding_table'):
        for i in range(len(encoding.decoding_table)):
            if encoding.decoding_table[i] == '\ufffe':
                print(f'{encoding_name}: byte 0x{i:02x} is corrupted')
                sys.exit(1)
    if hasattr(encoding, 'encoding_table'):
        for i in range(len(encoding.encoding_table)):
            if encoding.encoding_table[i] == '\ufffe':
                print(f'{encoding_name}: encoding byte 0x{i:02x} is corrupted')
                sys.exit(1)
except Exception as e:
    print(f'{encoding_name}: {e}')
" 2>&1
done

